import sys, cv2, numpy as np
sys.path.insert(0, "src")
import webcam as wc

print("=== camera is released and windows destroyed even on an exception ===")
cap_holder = {}
class Boom(Exception): pass
def exploding(frame):
    raise Boom("processing failed")
try:
    wc.run_webcam_loop(on_frame=exploding)
except Boom as e:
    print("  exception propagated out of the loop:", e)
# if the camera were still open, opening it again would fail or leak a handle
again = cv2.VideoCapture(wc.DEFAULT_CAMERA_INDEX)
print("  camera re-openable after the failure (was released):", again.isOpened())
ok, _ = again.read()
print("  and still delivering frames:", ok)
again.release()
cv2.destroyAllWindows()

print("\n=== KeyboardInterrupt mid-loop (Ctrl+C path) ===")
import signal
def interrupt_after(frame):
    if interrupt_after.n >= 5: raise KeyboardInterrupt
    interrupt_after.n += 1
    return frame
interrupt_after.n = 0
try:
    wc.run_webcam_loop(on_frame=interrupt_after)
except KeyboardInterrupt:
    print("  KeyboardInterrupt propagated as expected")
re2 = cv2.VideoCapture(0); print("  camera released:", re2.isOpened()); re2.release(); cv2.destroyAllWindows()

print("\n=== camera error handling ===")
for idx in (99, 7):
    try:
        with wc.open_webcam(idx) as c: print(f"  index {idx}: opened (unexpected)")
    except RuntimeError as e:
        print(f"  index {idx}: RuntimeError: {e}")

print("\n=== frame cannot be read (camera stopped delivering) ===")
with wc.open_webcam() as cap:
    cap.release()          # simulate the camera disappearing mid-session
    print("  read_frame after device gone ->", wc.read_frame(cap))

print("\n=== argument validation ===")
for bad, label in [(-1,"negative index"), (1.5,"float index"), ("0","string index"), (True,"bool index")]:
    try:
        wc.open_webcam(bad); print(f"  {label:16s} -> no error (unexpected)")
    except ValueError as e: print(f"  {label:16s} -> ValueError: {e}")
for bad in ("qq", "", 5, None):
    try:
        wc.run_webcam_loop(exit_key=bad); print(f"  exit_key {bad!r:6s} -> no error (unexpected)")
    except ValueError as e: print(f"  exit_key {bad!r:6s} -> ValueError: {e}")
